import { styled, Text } from '@tamagui/web';
import type { LabelHTMLAttributes, ReactNode, Ref } from 'react';
import { createContext, useContext } from 'react';

import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { cx } from '../../helpers/composeClassNames';
import type { PartAttributes } from '../../types/ElementAttributes';

export const LabelContext = createContext(false);

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

// Declared where they render: zero-runtime only erases a `styled()` whose every use is in its own module
const LabelFrame = styled(Text, {
	flexBasis: 'auto',
	whiteSpace: 'inherit',
	wordWrap: 'inherit',
	render: 'label',
	display: 'flex',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	cursor: 'default',
	color: 'var(--rcx-color-font-default, #2f343d)',
	fontSize: '0.875rem',
	fontWeight: 500,
	lineHeight: '1.25rem',
	letterSpacing: '0rem',
	variants: {
		unavailable: {
			true: {
				pointerEvents: 'none',
				color: 'var(--rcx-color-font-secondary-info, #6c737a)',
			},
			false: {},
		},
	},
});

// Declared where they render: zero-runtime only erases a `styled()` whose every use is in its own module
const LabelRequiredFrame = styled(Text, {
	render: 'span',
	display: 'inline',
	whiteSpace: 'normal',
	wordWrap: 'normal',
	marginInlineStart: '4px',
	color: 'var(--rcx-color-font-danger, #d40c26)',
});

// end of generated

export type LabelProps = PartAttributes<HTMLElement> &
	Pick<LabelHTMLAttributes<HTMLLabelElement>, 'htmlFor'> & {
		/** Renders a `span`, for a caption that names its control through `aria-labelledby`. Inside another label it is one. */
		is?: 'label' | 'span';
		disabled?: boolean;
		required?: boolean;
		children?: ReactNode;
	};

/**
 * A caption for an input component.
 */
function Label(props: LabelProps) {
	const { disabled, required, children } = props;
	const isInsideLabel = useContext(LabelContext);
	const className = cx('rcx-box rcx-box--full', { 'rcx-label--disabled': !!disabled }, 'rcx-label', props.className);
	const content = (
		<>
			{children}
			{required && (
				<LabelRequiredFrame render={<span aria-hidden='true' />} className='rcx-box rcx-box--full rcx-label__required'>
					*
				</LabelRequiredFrame>
			)}
		</>
	);

	// One branch per tag: zero-runtime has to know it
	if (props.is === 'span' || (!props.is && isInsideLabel)) {
		return (
			<LabelContext.Provider value={true}>
				<LabelFrame
					unavailable={Boolean(disabled)}
					className={className}
					render={
						<span
							{...ariaAndDataAttributes(props)}
							// The ref is typed for both tags, each branch renders one
							ref={props.ref}
							id={props.id}
							title={props.title}
						/>
					}
				>
					{content}
				</LabelFrame>
			</LabelContext.Provider>
		);
	}

	return (
		<LabelContext.Provider value={true}>
			<LabelFrame
				unavailable={Boolean(disabled)}
				className={className}
				render={
					<label
						{...ariaAndDataAttributes(props)}
						htmlFor={props.htmlFor}
						ref={props.ref as Ref<HTMLLabelElement>}
						id={props.id}
						title={props.title}
					/>
				}
			>
				{content}
			</LabelFrame>
		</LabelContext.Provider>
	);
}

export default Label;
